/**
 * The regression family of the lote 4 vetoes (lote4-request.ts), generated by combination: every refusal and every
 * request for guidance, before, after or inside the request, and the action of someone else (with a modal, reported or
 * asked about), over every request verb and object of C47, C01 and C09. Each phrase must keep the route origin/main
 * gives it (routing-regression.lote4-vetoes-main.json), with and without files. Test support only.
 */

const refusals: readonly ((v: {inf: string; subj: string}) => string)[] = [
  (v) => `Não ${v.subj}`,
  (v) => `Não quero ${v.inf}`,
  (v) => `Não preciso ${v.inf}`,
  (v) => `Não desejo ${v.inf}`,
  (v) => `Não gostaria de ${v.inf}`,
  (v) => `Não estou pedindo que você ${v.subj}`,
  (v) => `Não é para ${v.inf}`,
  (v) => `Ninguém pediu para ${v.inf}`,
  (v) => `Nem precisa ${v.inf}`,
  (v) => `Dispense ${v.inf}`,
  (v) => `Evite ${v.inf}`,
  (v) => `Deixe de ${v.inf}`,
  // Round 6: refusing and giving up, directly.
  (v) => `Recuso ${v.inf}`,
  (v) => `Rejeito ${v.inf}`,
  (v) => `Desista de ${v.inf}`,
  (v) => `Desisti de ${v.inf}`,
  (v) => `Abandone a ideia de ${v.inf}`,
  (v) => `Cancele o pedido para ${v.inf}`,
  (v) => `Esqueça a ideia de ${v.inf}`,
  (v) => `Pare de ${v.inf}`,
];

const guidance: readonly ((v: {inf: string; subj: string}) => string)[] = [
  (v) => `Como ${v.inf}`,
  (v) => `Como devo ${v.inf}`,
  (v) => `Como posso ${v.inf}`,
  (v) => `De que forma ${v.inf}`,
  (v) => `Qual a melhor forma de ${v.inf}`,
  (v) => `Me diga como ${v.inf}`,
  (v) => `Me explique como ${v.inf}`,
  (v) => `Me ensine a ${v.inf}`,
  (v) => `Me oriente sobre como ${v.inf}`,
  (v) => `Quero saber como ${v.inf}`,
];

const cap = (x: string) => x[0]!.toUpperCase() + x.slice(1);
/** A refusal after the action, or between its parts (independent review, round 5). */
const after: readonly ((v: {inf: string; subj: string}, o: string) => string)[] = [
  (v, o) => `${cap(v.inf)} ${o} não é o que eu quero.`,
  (v, o) => `${cap(v.inf)} ${o} não é o que eu pedi.`,
  (v, o) => `${cap(v.subj)} ${o}, mas não agora.`,
  (v, o) => `${cap(v.subj)} ${o}? Não, ainda não.`,
  (v, o) => `${cap(v.inf)} ${o}: dispenso por enquanto.`,
  (v, o) => `${cap(v.subj)} ${o} só se eu pedir; por ora, nem precisa.`,
];
const interleaved: readonly ((v: {inf: string; subj: string}, o: string) => string)[] = [
  (v, o) => `Não é necessário, por enquanto, ${v.inf} ${o}.`,
  (v, o) => `Por enquanto, não ${v.subj} ${o}.`,
  (v, o) => `${cap(v.subj)}, quer dizer, não ${v.subj} ainda, ${o}.`,
  (v, o) => `Eu sei ${v.inf} ${o}, me diga só como você faria.`,
  (v, o) => `${cap(v.subj)}, sem pressa e sem análise, ${o}.`,
];
/** Round 7: the subjects of someone else's action, and that action with a modal or as reported speech. */
const thirdParties: readonly [string, string][] = [["O banco", "o banco"], ["A diretoria", "a diretoria"], ["O CFO", "o CFO"], ["Eles", "eles"], ["O assessor deles", "o assessor deles"],
  ["Ela", "ela"], ["O gerente", "o gerente"]];
const othersByModal: readonly ((v: {inf: string; subj: string}, o: string, who: [string, string]) => string)[] = [
  (v, o, [S]) => `${S} pode ${v.inf} ${o}.`,
  (v, o, [, s]) => `Quando ${s} pode ${v.inf} ${o}?`,
  (v, o, [S]) => `${S} consegue ${v.inf} ${o}?`,
  (v, o, [S]) => `${S} poderia ${v.inf} ${o} na semana que vem.`,
  (v, o, [S]) => `${S} disse que ${o} é boa.`,
  (v, o, [S]) => `${S} acha que vale a pena ${v.inf} ${o}?`,
  (v, o, [, s]) => `Segundo ${s}, ${o} é boa?`,
  (v, o, [, s]) => `De acordo com ${s}, ${v.inf} ${o} faz sentido?`,
];
/** Round 8: every trigger (wanting verb, modal, "quer que") after a third-party subject. */
const triggersOfOthers: readonly ((v: {inf: string; subj: string}, o: string, who: [string, string]) => string)[] = [
  (v, o, [S]) => `${S} gostaria de ${v.inf} ${o}.`,
  (v, o, [S]) => `${S} queria ${v.inf} ${o}.`,
  (v, o, [S]) => `${S} quer ${v.inf} ${o}.`,
  (v, o, [S]) => `${S} precisa ${v.inf} ${o}.`,
  (v, o, [S]) => `${S} poderia ${v.inf} ${o}?`,
  (v, o, [S]) => `${S} quer que você ${v.subj} ${o}.`,
  (v, o, [S]) => `${S} disse que você pode ${v.inf} ${o}.`,
];
/** The requests addressed to the advisor that promote (the positives), and the same requests reported from a third party,
 * which never do: "X disse que", "X pediu que", "segundo X", "de acordo com X", "conforme X sugeriu". */
export const lote4AddressedRequests: readonly string[] = [
  "Prepare a discussão da dívida para o conselho.", "Monte a discussão de estrutura de capital para o conselho.", "Quero que você prepare a discussão da dívida para o conselho.",
  "Você consegue preparar a discussão da dívida para o conselho?", "Preciso preparar a discussão da dívida para o conselho.",
  "Avalie essa proposta de crédito do banco que o Itaú mandou.", "Pode avaliar a proposta de crédito que o Bradesco mandou?",
  "Por favor, pode me ajudar a avaliar a proposta de crédito do Itaú?", "O Itaú mandou essa proposta de CCB, é boa?",
  "Recebi uma proposta de CCB do Bradesco. Vale a pena?", "Essa proposta de crédito do Itaú é boa?", "Eu gostaria de avaliar essa proposta de crédito que recebemos.",
];
const reportedForms: readonly ((p: string, who: [string, string]) => string)[] = [
  (p, [S]) => `${S} disse que ${p[0]!.toLowerCase()}${p.slice(1)}`,
  (p, [S]) => `${S} pediu que ${p[0]!.toLowerCase()}${p.slice(1)}`,
  (p, [, s]) => `Segundo ${s}, ${p[0]!.toLowerCase()}${p.slice(1)}`,
  (p, [, s]) => `De acordo com ${s}, ${p[0]!.toLowerCase()}${p.slice(1)}`,
  (p, [, s]) => `Conforme ${s} sugeriu, ${p[0]!.toLowerCase()}${p.slice(1)}`,
];
/** Round 9: the same requests reported with a colon, in quotes or after a dash, by several speech verbs. */
const reportedQuoted: readonly ((p: string, who: [string, string]) => string)[] = [
  (p, [S]) => `${S} disse: ${p[0]!.toLowerCase()}${p.slice(1)}`,
  (p, [S]) => `${S} pediu: "${p}"`,
  (p, [S]) => `${S} escreveu \u201c${p}\u201d`,
  (p, [S]) => `${S} respondeu \u2014 ${p[0]!.toLowerCase()}${p.slice(1)}`,
  (p, [S]) => `${S} falou - ${p[0]!.toLowerCase()}${p.slice(1)}`,
  (p, [S]) => `${S} sugeriu: '${p}'`,
];
/** First person introducers keep the request the person's own (they promote). */
export const lote4OwnIntroducedRequests: readonly string[] = ["Eu disse: prepare a discussão da dívida para o conselho.", "Falei: pode avaliar a proposta de crédito que o Bradesco mandou?",
  "Nós pedimos: \u201cAvalie essa proposta de crédito do banco que o Itaú mandou.\u201d", "Eu escrevi \u2014 prepare a discussão da dívida para o conselho."];
/** Round 6: the action of someone else, reported or asked about, never a request to the advisor. */
const others: readonly ((v: {inf: string; subj: string}, o: string) => string)[] = [
  (v, o) => `O banco vai ${v.inf} ${o}.`,
  (v, o) => `A diretoria vai ${v.inf} ${o}.`,
  (v, o) => `Quando o banco vai ${v.inf} ${o}?`,
  (v, o) => `O CFO ficou de ${v.inf} ${o} na semana que vem.`,
  (v, o) => `A equipe de tesouraria pretende ${v.inf} ${o}.`,
];
const methods: readonly {verbs: {inf: string; subj: string}[]; objects: string[]}[] = [
  // C47, the board's capital discussion.
  {verbs: [{inf: "preparar", subj: "prepare"}, {inf: "montar", subj: "monte"}, {inf: "elaborar", subj: "elabore"}, {inf: "fazer", subj: "faça"}],
    objects: ["a discussão da dívida para o conselho", "o material do conselho sobre a estrutura de capital", "o deck do conselho sobre o financiamento"]},
  // C01, the received proposal.
  {verbs: [{inf: "avaliar", subj: "avalie"}, {inf: "analisar", subj: "analise"}, {inf: "olhar", subj: "olhe"}],
    objects: ["essa proposta de crédito do banco", "a proposta de CCB que o Itaú mandou", "o term sheet que o Bradesco enviou"]},
  // C09, the document folder.
  {verbs: [{inf: "organizar", subj: "organize"}, {inf: "arrumar", subj: "arrume"}, {inf: "separar", subj: "separe"}],
    objects: ["a pasta de documentos", "os arquivos que subimos", "o material que joguei aqui"]},
];

/** Every phrase of the family, refusals with a period and requests for guidance as questions. */
export function lote4VetoFamily(): string[] {
  const out: string[] = [];
  for (const m of methods) for (const v of m.verbs) for (const o of m.objects) {
    for (const r of refusals) out.push(`${r(v)} ${o}.`);
    for (const g of guidance) out.push(`${g(v)} ${o}?`);
    for (const r of after) out.push(r(v, o));
    for (const r of interleaved) out.push(r(v, o));
    for (const r of others) out.push(r(v, o));
    for (const who of thirdParties) for (const r of othersByModal) out.push(r(v, o, who));
    for (const who of thirdParties) for (const r of triggersOfOthers) out.push(r(v, o, who));
  }
  for (const p of lote4AddressedRequests) for (const who of thirdParties) for (const r of reportedForms) out.push(r(p, who));
  for (const p of lote4AddressedRequests) for (const who of thirdParties) for (const r of reportedQuoted) out.push(r(p, who));
  return out;
}
